import{_ as t,a as r,o as d,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"List Returnable Orders","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-returnable-orders","title":"List Returnable Orders","description":"The customer's orders a return can still be raised against — the list the New Request flow opens with.","request":"GET /api/shop/returnable-orders\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"[\\n  {\\n    \\"id\\": 41,\\n    \\"incrementId\\": \\"41\\",\\n    \\"status\\": \\"completed\\",\\n    \\"statusLabel\\": \\"Completed\\",\\n    \\"grandTotal\\": 160.0,\\n    \\"formattedGrandTotal\\": \\"$160.00\\",\\n    \\"orderCurrencyCode\\": \\"USD\\",\\n    \\"paymentMethodTitle\\": \\"Cash On Delivery\\",\\n    \\"totalQtyOrdered\\": 3,\\n    \\"totalReturnedQty\\": 1,\\n    \\"returnableQty\\": 2,\\n    \\"createdAt\\": \\"2026-08-30 09:12:44\\"\\n  }\\n]\\n","commonErrors":[{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"401 Unauthorized","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"}]},{"id":"list-returnable-orders-filtered","title":"Filter by Order Number","description":"Narrow the list to one order number, or to a status, and choose the sort.","request":"GET /api/shop/returnable-orders?increment_id=41&sort=grand_total&order=desc\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"[\\n  {\\n    \\"id\\": 41,\\n    \\"incrementId\\": \\"41\\",\\n    \\"status\\": \\"completed\\",\\n    \\"statusLabel\\": \\"Completed\\",\\n    \\"grandTotal\\": 160.0,\\n    \\"formattedGrandTotal\\": \\"$160.00\\",\\n    \\"orderCurrencyCode\\": \\"USD\\",\\n    \\"paymentMethodTitle\\": \\"Cash On Delivery\\",\\n    \\"totalQtyOrdered\\": 3,\\n    \\"totalReturnedQty\\": 1,\\n    \\"returnableQty\\": 2,\\n    \\"createdAt\\": \\"2026-08-30 09:12:44\\"\\n  }\\n]\\n","commonErrors":[{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/returns/list-returnable-orders.md","filePath":"api/rest-api/shop/returns/list-returnable-orders.md","lastUpdated":1789385991000}`),o={name:"api/rest-api/shop/returns/list-returnable-orders.md"};function n(s,e,i,l,h,c){return d(),r("div",null,e[0]||(e[0]=[a('<h1 id="list-returnable-orders" tabindex="-1">List Returnable Orders <a class="header-anchor" href="#list-returnable-orders" aria-label="Permalink to &quot;List Returnable Orders&quot;">​</a></h1><p>The authenticated customer&#39;s orders that can still start a return. This is the first screen of a return: pick an order here, then read its items from <a href="/api/rest-api/shop/returns/list-returnable-items.html">List Returnable Items</a> and submit with <a href="/api/rest-api/shop/returns/create-return.html">Create Return</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/returnable-orders</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="when-an-order-appears" tabindex="-1">When an Order Appears <a class="header-anchor" href="#when-an-order-appears" aria-label="Permalink to &quot;When an Order Appears&quot;">​</a></h2><p>An order is listed while all of the following hold. They are evaluated per item, so one eligible item is enough to list the order.</p><ol><li><strong>The item was sold with returns allowed.</strong> Eligibility is captured when the order is placed, from the product type the store permits returns for. An item placed while returns were off never becomes returnable later.</li><li><strong>The return window is still open.</strong> Each item carries its own window, taken from the store&#39;s return period at the time of purchase, counted from the item&#39;s own date.</li><li><strong>Quantity is left.</strong> Everything already requested on that item is subtracted; once the whole quantity is covered, the order drops off the list.</li><li><strong>The order is in a usable state.</strong> Canceled, closed, fraud and pending-payment orders never appear.</li></ol><p>An empty array means the customer has nothing to return right now — show that rather than an error.</p><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>increment_id</code></td><td>string</td><td>No</td><td>Match the order number, partially.</td></tr><tr><td><code>status</code></td><td>string</td><td>No</td><td>Match the order status exactly, e.g. <code>completed</code> or <code>processing</code>.</td></tr><tr><td><code>sort</code></td><td>string</td><td>No</td><td><code>created_at</code> (default), <code>increment_id</code> or <code>grand_total</code>.</td></tr><tr><td><code>order</code></td><td>string</td><td>No</td><td><code>desc</code> (default) or <code>asc</code>.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Order id — pass this as <code>order_id</code> to the returnable-items and create endpoints.</td></tr><tr><td><code>incrementId</code></td><td>string</td><td>Order number as the customer sees it.</td></tr><tr><td><code>status</code></td><td>string</td><td>Order status.</td></tr><tr><td><code>statusLabel</code></td><td>string</td><td>Translated status, ready to display.</td></tr><tr><td><code>grandTotal</code></td><td>number</td><td>Order total in the order&#39;s currency.</td></tr><tr><td><code>formattedGrandTotal</code></td><td>string</td><td>Total formatted in the order&#39;s currency.</td></tr><tr><td><code>orderCurrencyCode</code></td><td>string</td><td>Currency the order was placed in.</td></tr><tr><td><code>paymentMethodTitle</code></td><td>string</td><td>Payment method title, or <code>null</code> when the order has none recorded.</td></tr><tr><td><code>totalQtyOrdered</code></td><td>integer</td><td>Quantity across the order&#39;s returnable items.</td></tr><tr><td><code>totalReturnedQty</code></td><td>integer</td><td>Quantity already covered by returns.</td></tr><tr><td><code>returnableQty</code></td><td>integer</td><td>What is left — <code>totalQtyOrdered</code> minus <code>totalReturnedQty</code>.</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>When the order was placed.</td></tr></tbody></table><p><code>returnableQty</code> is a whole-order figure for display. The per-item caps the server actually enforces come from <a href="/api/rest-api/shop/returns/list-returnable-items.html">List Returnable Items</a>.</p><h2 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200 OK</code></td><td>The list, possibly empty.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid storefront key.</td></tr><tr><td><code>403 Forbidden</code></td><td>Missing or invalid customer Bearer token.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/returns/list-returnable-items.html">List Returnable Items</a> — the items of a chosen order, with the quantity caps</li><li><a href="/api/rest-api/shop/returns/create-return.html">Create Return</a> — raise the return</li><li><a href="/api/rest-api/shop/returns/">Returns Overview</a> — how the returns menu works</li></ul>',19)]))}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
